    add     0x500086a8, d0
    extbu   d1
    mov     0x23, d2
    nop
    nop
    mulu    d2, d1
    add     d1, d0
    mov     d0, a2
    mov     TgDrawbarToneRecInit_Table, a1
    mov     a2, a0
    mov     -0x23, d1
    setlb
    movbu   (a1), d0
    inc     a1
    movbu   d0, (a0)
    inc     a0
    inc     d1
    lne
    movbu   (0x1c, sp), d1
    clr     d0
    and     0x7f, d1
    mov     d1, a1
    clr     d2
    mov     5, d3
    add     a2, d3
    setlb
    extbu   d0
    mov     d0, d1
    asl2    d1
    add     d0, d1
    add     d3, d1
    mov     d1, a0
    mov     a1, d0
    movbu   d0, (a0)
    movbu   (0x20, sp), d0
    inc     d2
    movbu   d0, (1, a0)
    movbu   (0x24, sp), d0
    movbu   d0, (2, a0)
    mov     d2, d0
    extbu   d2
    cmp     6, d2
    llt
    mov     a2, a0
    ret     [d2,d3,a2], 0xc
